import narwhals as nw
import pandas as pd
import polars as pl

@nw.narwhalify
def add_total(df):
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )

# Test with pandas
pdf = pd.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
print("Pandas result:")
print(add_total(pdf))

# Test with polars
pf = pl.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
print("\nPolars result:")
print(add_total(pf))
